import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"19、【臨】 兌下坤上","description":"橫渠易說 - 19、【臨】 兌下坤上","frontmatter":{"title":"19、【臨】 兌下坤上","description":"橫渠易說 - 19、【臨】 兌下坤上"},"headers":[],"relativePath":"classics/hengqu/021.md","filePath":"classics/hengqu/021.md"}'),l={name:"classics/hengqu/021.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_19、【臨】-兌下坤上" tabindex="-1">19、【臨】 兌下坤上 <a class="header-anchor" href="#_19、【臨】-兌下坤上" aria-label="Permalink to “19、【臨】 兌下坤上”">​</a></h1><h3 id="彖曰-臨-剛浸而長-說而順-剛中而應。大亨以正-天之道也。-至於八月有兇-消不久也。" tabindex="-1">彖曰：臨，剛浸而長，說而順，剛中而應。大亨以正，天之道也。“至於八月有兇”，消不久也。 <a class="header-anchor" href="#彖曰-臨-剛浸而長-說而順-剛中而應。大亨以正-天之道也。-至於八月有兇-消不久也。" aria-label="Permalink to “彖曰：臨，剛浸而長，說而順，剛中而應。大亨以正，天之道也。“至於八月有兇”，消不久也。”">​</a></h3><h3 id="象曰-澤上有地-臨-君子以教思無窮-容保民無疆。" tabindex="-1">象曰：澤上有地，臨，君子以教思無窮，容保民無疆。 <a class="header-anchor" href="#象曰-澤上有地-臨-君子以教思無窮-容保民無疆。" aria-label="Permalink to “象曰：澤上有地，臨，君子以教思無窮，容保民無疆。”">​</a></h3><p>臨言“有兇”者，大抵易之於爻，變陽至二，便為之戒，恐有過滿之萌。未過中已戒，猶履霜堅冰之義，及泰之三曰：“無平不陂，無往不復”，皆過中之戒也。</p><h3 id="初九-鹹臨-貞吉。-象曰-鹹臨貞吉-志行正也。" tabindex="-1">初九，鹹臨，貞吉。 象曰：“鹹臨貞吉”，志行正也。 <a class="header-anchor" href="#初九-鹹臨-貞吉。-象曰-鹹臨貞吉-志行正也。" aria-label="Permalink to “初九，鹹臨，貞吉。 象曰：“鹹臨貞吉”，志行正也。”">​</a></h3><p>臨為剛長，己志應上，故雖感而行正也。</p><h3 id="九二-鹹臨-吉-無不利。-象曰-鹹臨吉無不利-未順命也。" tabindex="-1">九二，鹹臨，吉，無不利。 象曰：“鹹臨吉無不利”，未順命也。 <a class="header-anchor" href="#九二-鹹臨-吉-無不利。-象曰-鹹臨吉無不利-未順命也。" aria-label="Permalink to “九二，鹹臨，吉，無不利。 象曰：“鹹臨吉無不利”，未順命也。”">​</a></h3><p>非鹹則有上下之疑，有所不利。</p><h3 id="六三-甘臨-無攸利。既憂之-無咎。-象曰-甘臨-位不當也。-既憂之-咎不長也。" tabindex="-1">六三，甘臨，無攸利。既憂之，無咎。 象曰：“甘臨”，位不當也。“既憂之”，咎不長也。 <a class="header-anchor" href="#六三-甘臨-無攸利。既憂之-無咎。-象曰-甘臨-位不當也。-既憂之-咎不長也。" aria-label="Permalink to “六三，甘臨，無攸利。既憂之，無咎。 象曰：“甘臨”，位不當也。“既憂之”，咎不長也。”">​</a></h3><p>體說乘剛故甘，邪說求容而以臨物，安有所利!能自憂懼，庶可免咎。</p><h3 id="六四-至臨-無咎。-象曰-至臨無咎-位當也。" tabindex="-1">六四，至臨，無咎。 象曰：“至臨無咎”，位當也。 <a class="header-anchor" href="#六四-至臨-無咎。-象曰-至臨無咎-位當也。" aria-label="Permalink to “六四，至臨，無咎。 象曰：“至臨無咎”，位當也。”">​</a></h3><p>以陰居陰，體順應正，盡臨之道，雖在剛長，可以無咎。正一作說。</p><h3 id="六五-知臨-大君之宜-吉。-象曰-大君之宜-行中之謂也。" tabindex="-1">六五，知臨，大君之宜，吉。 象曰：“大君之宜”，行中之謂也。 <a class="header-anchor" href="#六五-知臨-大君之宜-吉。-象曰-大君之宜-行中之謂也。" aria-label="Permalink to “六五，知臨，大君之宜，吉。 象曰：“大君之宜”，行中之謂也。”">​</a></h3><p>順命行中，天子之宜。</p><h3 id="上六-敦臨-吉-無咎。-象曰-敦臨之吉-志在內也。" tabindex="-1">上六，敦臨，吉，無咎。 象曰：敦臨之吉，志在內也。 <a class="header-anchor" href="#上六-敦臨-吉-無咎。-象曰-敦臨之吉-志在內也。" aria-label="Permalink to “上六，敦臨，吉，無咎。 象曰：敦臨之吉，志在內也。”">​</a></h3><p>體順則無所違，極上則無所進，不以無應而志在於臨，故曰敦臨志在內也。</p>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
